INSERT INTO `about_fabric_technology_sections` (`id`, `image`, `section_title`, `title`, `description`, `button_title`, `button_link`, `button_enabled`, `created_at`, `updated_at`) VALUES
(1, '/uploads/about/fabric-technology/1784967568_about_fabric_tech_6a6471909ba8f7.06324457.png', 'Fabric & Technology', 'Fabric, Engineered with Purpose', 'Every Viveren fabric is engineered with purpose. From structured knits to breathable, compostable blends, our materials are selected to deliver comfort, durability, and effortless wear — without compromise.', 'Discover Our Fabrics', '/sustainability', 1, '2026-07-16 04:55:05', '2026-07-25 12:41:07');
INSERT INTO `about_giving_back_sections` (`id`, `image`, `section_title`, `title`, `description`, `points`, `button_title`, `button_link`, `button_enabled`, `created_at`, `updated_at`) VALUES
(1, 'uploads/about/giving-back/1784969325_about_giving_back_6a64786d2bdf14.66748373.png', 'Sustainability', 'Responsibility, Built In', 'Viveren believes the future of fashion is honest, human, and considered.\r\n\r\nThe clothes you wear should feel good — on your body, in your values, and in the world you move through.', '[\"Ethical Sourcing\",\"Eco-Friendly Materials\",\"Carbon Neutral Shipping\"]', 'Explore Our Sustainability Approach', '#', 1, '2026-07-16 04:55:04', '2026-07-25 12:48:45');
INSERT INTO `about_hero_sections` (`id`, `background_image`, `section_title`, `title`, `description`, `created_at`, `updated_at`) VALUES
(1, '/uploads/about/hero/1784550617_about_hero_6a5e14d953fcb5.37550518.png', 'Our Story', 'Elevated Athleisure thoughfully made', 'Inspired by ‘vivere” meaning : to live , VIVEREN creates timeless essentials\r\nwith premium craftsmanship and lasting comfort.\r\nUsing reponsible materials to help lower environmental impact.', '2026-07-16 04:54:58', '2026-07-23 19:10:44');
