INSERT INTO `about_story_sections` (`id`, `background_image`, `section_title`, `title`, `description_html`, `created_at`, `updated_at`) VALUES
(1, 'uploads/about/story/1784970709_about_story_6a647dd5623804.68422358.png', 'Crafted for comfort.', 'Our Mission', '<p>Our mission is to design clothing that supports real life — comfortably, honestly, and with quiet confidence. We create elevated essentials that move with you through everyday moments, blending thoughtful design, ethical choices, and effortless wearability.</p>', '2026-07-16 04:54:58', '2026-07-25 13:11:49');
