INSERT INTO `community_page_sections` (`id`, `key`, `title`, `description`, `content_title`, `heading`, `section_description`, `button_text`, `button_url`, `feature_image`, `feature_image_2`, `our_materials_items`, `feature_items`, `community_image`, `community_items`, `gallery_items`, `status`, `created_at`, `updated_at`) VALUES
(1, 'hero', 'Hero Section', 'Top campaign headline and CTA.', 'Our Responsibility', 'Sustainability & Responsibility', 'How We Think, Design, and Build with Care', 'Let\'s Make a Purchase', '/products', NULL, NULL, NULL, '[]', NULL, '[]', '[]', 'active', '2026-07-16 04:38:57', '2026-07-16 04:46:49'),
(2, 'longevity', 'Designed for Longevity', 'Sustainability daily-practice story section.', 'SUSTAINABILITY, PRACTICED DAILY', 'Designed for Longevity', 'At Viveren, sustainability isn’t a statement—it’s a daily discipline. It’s built through thoughtful, consistent choices across design, materials, and craftsmanship, always prioritizing longevity over volume and progress over perfection.\n\nAs we grow, we remain committed to transparency and continuous improvement—exploring lower-impact materials, refining our processes, and investing in responsible innovation. Because real change happens quietly, consistently, and with intention.', NULL, NULL, '/uploads/community/features/1784969479_community_feature_6a647907f20485.48990986.jpeg', NULL, '[]', '[]', NULL, '[]', '[]', 'active', '2026-07-17 22:07:56', '2026-07-25 12:51:22'),
(3, 'mindful-materials', 'Thoughtfully Chosen Materials', 'Mindful materials and composition highlights.', 'MINDFUL MATERIALS', 'Thoughtfully Chosen Materials', 'Our fabrics are selected with equal care for comfort on the body and respect for the planet. We prioritize materials with lower environmental impact while continually exploring better alternatives as innovation evolves.\n\nModal for exceptional softness, breathability, and durability\nBCI Cotton to support improved farming practices and responsible water use\nCertified Recycled Polyester to reduce reliance on virgin ressources.\nRecycled ocean plastic bottles repurposed as soft and lasting polyester [ Summer 2027 ].\nCompostable Polyester [ CELYS] under our label CircleLooms [ Early Spring 2027 ].\nBamboo-derived Viscose for its renewable origins and natural softness.', NULL, NULL, '/uploads/community/features/1784970574_community_feature_6a647d4e119906.93076152.png', NULL, '[]', '[]', NULL, '[]', '[]', 'active', '2026-07-18 00:32:19', '2026-07-25 13:09:36'),
(4, 'behind-the-craft', 'Behind the Craft', 'Craft process and people-first production section.', 'Fabric & Technology', 'Behind the Craft', '• Built in our own factory, with respect at the core.\n• Human-first production. Fair labor, responsible environment.\n• Integrity woven into every garment\n\nAs owners of our manufacturing facility, we maintain direct oversight of how our garments are made.\n\nThis allows us to uphold ethical labor practices, ensure safe and respectful working conditions, maintain consistent quality, and reduce unnecessary supply-chain complexity. Our factory operates with eco-responsible principles, aligning every stage of production with our environmental and human values.', NULL, NULL, '/uploads/community/features/1784970498_community_feature_6a647d02acfae9.50491167.png', '/uploads/community/features/1784970505_community_feature_6a647d099ef1d1.49350641.png', '[]', '[]', NULL, '[]', '[]', 'active', '2026-07-18 00:53:47', '2026-07-25 13:08:29'),
(5, 'fabric-innovations', 'Our Materials', 'Material innovation and performance story section.', 'OUR MATERIALS', 'Signature Fabric Innovations', NULL, NULL, NULL, NULL, NULL, '[{\"id\":\"our-materials-item-1784968736220\",\"contentHeader\":\"FlexTwill\",\"contentTitle\":\"Structured. Supple. Everyday-Ready.\",\"details\":\"A compact knit with a refined twill surface. Crisp in appearance yet soft to the touch, FlexTwill delivers polish without stiffness \\u2014 ideal for all-day, everyday wear.\",\"image\":\"\\/uploads\\/community\\/features\\/1784970544_community_feature_6a647d30bfc901.84610312.png\"},{\"id\":\"our-materials-item-1784970852526\",\"contentHeader\":\"Dual Skin Scuba\",\"contentTitle\":\"Soft Structure with Depth.\",\"details\":\"A cotton-based double knit with subtle two-tone depth. Breathable, lightweight, and gently supportive \\u2014 designed for comfort with a premium feel.\",\"image\":\"\\/uploads\\/community\\/features\\/1784971025_community_feature_6a647f11ea8307.22934591.png\"},{\"id\":\"our-materials-item-1784971168150\",\"contentHeader\":\"Soft Skin Scuba\",\"contentTitle\":\"Smooth. Modern. Fluid.\",\"details\":\"A cotton-based double knit with subtle two-tone depth. Breathable, lightweight, and gently supportive \\u2014 designed for comfort with a premium feel.\",\"image\":\"\\/uploads\\/community\\/features\\/1784971279_community_feature_6a64800f8b6b75.70758741.png\"},{\"id\":\"our-materials-item-1784971401065\",\"contentHeader\":\"CircleLooms\",\"contentTitle\":\"Naturally Gentle. Thoughtfully Made.\",\"details\":\"A next-generation compostable knit crafted from B.I.C(Better Cotton Initiative) and CELYS fibers. Soft on the skin, breathable, and thoughtfully made for mindful everyday comfort.\",\"image\":\"\\/uploads\\/community\\/features\\/1784971595_community_feature_6a64814b774aa2.06896081.png\"}]', '[]', NULL, '[]', '[]', 'active', '2026-07-25 12:48:21', '2026-07-25 13:26:43');
